/**
 * McDropNodeView: the in-conversation drop record. One compact row at the
 * replaced tool output's position: the dropped tag and the freed token count.
 */
import type { PropsLocale, PropsRuntime } from '@deepseek-ai/dsh-client-ui-slots'
import type { McDropChatData } from './index.ts'
import css from './McDropNodeView.module.css'

export type McDropNodeViewProps = PropsRuntime<'conversation.chat.node', 'mc-drop'> & PropsLocale<'mc'>

export function McDropNodeView({ node, t }: McDropNodeViewProps) {
  const data = node.data as McDropChatData
  return (
    <div className={css.row} title="Magic Context freed this tool output from the context">
      <span className={css.glyph} aria-hidden>⧉</span>
      <span className={css.label}>{t('dropped')}</span>
      <span className={css.tag}>{`[dropped §${data.tagId}§]`}</span>
      {data.shadowedTokens > 0 && (
        <span className={css.tokens}>{`−${data.shadowedTokens} tok`}</span>
      )}
    </div>
  )
}
