/**
 * Magic Context DSH client half: the in-conversation drop records.
 *
 * The drop record rides the chat-node extension seam: a ConversationNode
 * definition folds the `mc/drop-meter` (log-only, carries the shadowed token
 * count) and the adjacent `tool/result` replacement (the `[dropped §N§]`
 * placeholder) into one `mc-drop` chat node, rendered in the conversation
 * flow where the original tool output was.
 *
 * The token-breakdown panel was removed by design decision: the harness
 * ships its own ContextMeter next to the send button, and a companion
 * breakdown button was redundant.
 */
import type {
  ChatConversationViewNode,
  ClientContext,
  ConversationLocation,
  ConversationMatch,
  ConversationMatchResult,
  ConversationNodeContext,
  ConversationNodeDefinition,
} from '@deepseek-ai/dsh-client-runtime/client'
import type { SessionEvent } from '@deepseek-ai/dsh-session/types'
// Type-only: pulls the ui-conversation SlotMap merge (the chat node seat).
import type {} from '@deepseek-ai/dsh-client-ui-conversation/client'
// Type-only: pulls the locale plugin's Context merge (ctx.locale).
import type {} from '@deepseek-ai/dsh-client-locale/client'
import { McDropNodeView } from './McDropNodeView.tsx'
import { en, zh, type McKey } from './locales.ts'

declare module '@deepseek-ai/dsh-session/types' {
  interface SessionEventMap {
    /** Shadow-price metering for a ctx_reduce drop replacement (log-only, informational). */
    'mc/drop-meter': {
      shadowedSeqs: number[]
      rawTokens: number
      checkpointTokens: number
      droppedTokens: number
    }
  }
}

/** Chat renderer payload for one committed drop. */
export interface McDropChatData {
  tagId: number
  shadowedTokens: number
}

declare module '@deepseek-ai/dsh-client-ui-conversation/client' {
  interface ChatNodeDataMap {
    'mc-drop': McDropChatData
  }
}

declare module '@deepseek-ai/dsh-client-ui-slots' {
  interface LocaleNamespaceMap {
    mc: McKey
  }
}

/** Dictionary namespace owned by this plugin. */
const NS = 'mc'

/** Drop-record state: the shadowed token count from the meter event. */
interface McDropState {
  tagId: number
  shadowedTokens: number
}

const DROP_MARKER_RE = /§(\d+)§/
const DROP_PLACEHOLDER_RE = /^\[dropped §(\d+)§\]$/

/** Full text of one tool-result message, joined from its content blocks. */
function toolResultText(event: SessionEvent): string {
  const data = event.data as unknown as { message?: { content?: Array<{ content?: Array<{ text?: string }> }> } }
  return data.message?.content?.[0]?.content?.map((b) => b.text ?? '').join(' ') ?? ''
}

/**
 * One `mc-drop` node per replaced tool output. The meter event starts the
 * node with the token delta; the adjacent replacement finalizes it with the
 * tag id (from the placeholder text) and the render anchor.
 */
const mcDropDefinition: ConversationNodeDefinition<McDropState> = {
  kind: 'mc-drop',
  target: 'chat',
  match: (event: SessionEvent): ConversationMatchResult | null => {
    if (event.type === 'mc/drop-meter') {
      const anchorSeq = event.data.shadowedSeqs[0]
      if (typeof anchorSeq !== 'number') return null
      return { id: `mc-drop:${anchorSeq}`, role: 'start' }
    }
    if (event.type === 'tool/result' && (event as { surfaceOp?: { op?: string } }).surfaceOp?.op === 'replace') {
      // Only claim Magic Context drops: the in-box tool-output pruner emits
      // same-shaped tool/result replacements, and this node must not hijack
      // those. The ctx_reduce placeholder is the discriminator.
      if (!DROP_PLACEHOLDER_RE.test(toolResultText(event))) return null
      const seqs = (event as { sourceEventSeqs?: number[] }).sourceEventSeqs ?? []
      const anchorSeq = seqs[0]
      if (typeof anchorSeq !== 'number') return null
      return { id: `mc-drop:${anchorSeq}`, role: 'update' }
    }
    return null
  },
  start: (_context: ConversationNodeContext<McDropState>, match: ConversationMatch, _reader: unknown): McDropState => {
    const event = match.event as unknown as { data?: { rawTokens?: number } }
    return { tagId: 0, shadowedTokens: event.data?.rawTokens ?? 0 }
  },
  update: (
    context: ConversationNodeContext<McDropState> & { readonly state: McDropState },
    match: ConversationMatch,
  ): McDropState => {
    const marker = DROP_MARKER_RE.exec(toolResultText(match.event))
    const tagId = marker === null ? context.state.tagId : Number.parseInt(marker[1] ?? '0', 10)
    return { ...context.state, tagId }
  },
  buildViewNode: (context: ConversationNodeContext<McDropState>): ChatConversationViewNode | null => {
    // History windows page at append-origin boundaries: a page cut can leave
    // the drop placeholder update without its meter start (or vice versa).
    // Derive the render payload from every match instead of trusting state
    // alone, so a cut window still renders the tag it can see.
    let tagId = context.state?.tagId ?? 0
    let shadowedTokens = context.state?.shadowedTokens ?? 0
    for (const match of context.matches) {
      if (match.event.type === 'mc/drop-meter') {
        shadowedTokens = (match.event.data as { rawTokens?: number }).rawTokens ?? shadowedTokens
      } else if (match.event.type === 'tool/result') {
        const marker = DROP_PLACEHOLDER_RE.exec(toolResultText(match.event))
        if (marker !== null) tagId = Number.parseInt(marker[1] ?? '0', 10)
      }
    }
    const location: ConversationLocation =
      context.start?.location ?? context.matches[0]?.location ?? { kind: 'unresolved' }
    const anchor = context.start?.event.seq ?? context.matches[0]?.event.seq ?? 0
    return {
      key: context.key,
      kind: 'mc-drop',
      id: context.id,
      target: 'chat',
      anchorSeq: anchor + 0.02,
      location,
      visibility: 'visible',
      data: { tagId, shadowedTokens },
    }
  },
}

/** Required services: the drop node seat, its registry, locale dictionaries. */
export const inject = ['slots', 'conversationEvents', 'locale']

/**
 * Client plugin body: the drop-record node.
 */
export function apply(ctx: ClientContext): void {
  ctx.effect(() => ctx.locale.register(NS, { zh, en }), 'mc: dictionaries')
  ctx.conversationEvents.register(mcDropDefinition)
  ctx.slots.inject('conversation.chat.node', () => ctx.slots.register(
    { name: 'conversation.chat.node', key: 'mc-drop', locale: NS },
    McDropNodeView,
  ))
}
